_patrimonial = EXCLUDED.nota_arquitetura_patrimonial, plano_patrimonial = EXCLUDED.plano_patrimonial, plano_apresentado = EXCLUDED.plano_apresentado, caminho = EXCLUDED.caminho, momento = EXCLUDED.momento, motivo_nota = EXCLUDED.motivo_nota, melhoria = EXCLUDED.melhoria, razao_positiva = EXCLUDED.razao_positiva, retencao_5_anos = EXCLUDED.retencao_5_anos, comentario_adicional = EXCLUDED.comentario_adicional, reunioes_realizadas = EXCLUDED.reunioes_realizadas, inicio_programa = EXCLUDED.inicio_programa, versao_formulario = EXCLUDED.versao_formulario, fonte_arquivo = EXCLUDED.fonte_arquivo, fonte_aba = EXCLUDED.fonte_aba, id_resposta = EXCLUDED.id_resposta, ref_programa = EXCLUDED.ref_programa, ref_ep = EXCLUDED.ref_ep, imported_at = now();
