INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('hash:e28b52fbaae28a42d1c66685e215ee4de361e4f95791ddee31ce011b566897d0', '2026-Q1', 'Mar/2026', '2026-03-23T19:29'::timestamptz, 'Bruno Santos Jales', 'bruno santos jales', 'PHARUS', 'Hendrick Dorner', 8.0, 'Neutro', 10.0, NULL, NULL, NULL, NULL, NULL, NULL, 'Perdi o vínculo com o projeto e preciso retomar', NULL, 'O suporte do assessor é excelente. No meu caso em específico, até pela conversa que tive com o Vitor antes do fechamento, onde falei de meus investimentos e intenções dentro do programa, esperava mais do plano apresentado. Inclusive algo que me trouxe para o programa foi a possibilidade de realizar operações mais complexas, o que depois fui entender que era somente no programa Davos. Resumindo, no meu modo de entender, na situação que meu patrimônio e encontrava, esperava estratégias mais elaboradas. Muitas das coisas apresentadas eu já estava com elas em andamento, como aquisição de imóvel na planta, imóvel para Airbnb, já investia no mercado financeiro, renda fixa, etc. Entendo que o PHARUS seja algo para estruturar vidas financeiras que não estejam bem e “educar” pessoas que não tenham contato prévio com investimentos ou algo do tipo. E em minha conversa com o Vitor, na qual inclusive fui convidado para a mansão davos, mas não pude ir por questões de trabalho, esperava ver algum efeito maior em meu patrimônio dentro do programa. Enfim, opinião.', NULL, 'Preciso de algo que realmente mude o patamar do meu patrimônio, ver efeitos práticos e retornos na minha renda para valer a pena o investimento necessário.', 'Não.', NULL, NULL, 'legado', 'NPS_Q1_2026_ENVIADO_MARCO.xlsx', 'pharus', NULL, 'aba PHARUS da planilha', 'MARÇO') ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente = EXCLUDED.cliente, id_cliente = EXCLUDED.id_cliente, programa = EXCLUDED.programa, ep = EXCLUDED.ep, nota_nps = EXCLUDED.nota_nps, categoria = EXCLUDED.categoria, nota_estrategista = EXCLUDED.nota_estrategista, nota_backoffice = EXCLUDED.nota_backoffice, nota_qv360 = EXCLUDED.nota_qv360, nota_arquitetura_patrimonial = EXCLUDED.nota_arquitetura_patrimonial, plano_patrimonial = EXCLUDED.plano_patrimonial, plano_apresentado = EXCLUDED.plano_apresentado, caminho = EXCLUDED.caminho, momento = EXCLUDED.momento, motivo_nota = EXCLUDED.motivo_nota, melhoria = EXCLUDED.melhoria, razao_positiva = EXCLUDED.razao_positiva, retencao_5_anos = EXCLUDED.retencao_5_anos, comentario_adicional = EXCLUDED.comentario_adicional, reunioes_realizadas = EXCLUDED.reunioes_realizadas, inicio_programa = EXCLUDED.inicio_programa, versao_formulario = EXCLUDED.versao_formulario, fonte_arquivo = EXCLUDED.fonte_arquivo, fonte_aba = EXCLUDED.fonte_aba, id_resposta = EXCLUDED.id_resposta, ref_programa = EXCLUDED.ref_programa, ref_ep = EXCLUDED.ref_ep, imported_at = now();
