INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('hash:fa310ee98a71d361aefde9e99e0b423ba70df6823d4a8f40296f1005b052690c', '2026-Q1', 'Mar/2026', '2026-03-24T16:48'::timestamptz, 'Rene Carvalho Bayma', 'rene carvalho bayma', 'PHARUS', 'Ariel Phelipe Zocoli', 7.0, 'Neutro', 8.0, NULL, NULL, NULL, NULL, NULL, 'Em progresso, mas com dúvidas', 'Estou travado em alguma parte e preciso de ajuda', NULL, 'Melhorar a explicação e acompanhamento na operacionalização prática de cada mecanismo de construção de patrimônio. Dar mais suporte prático nesse ponto. Por exemplo: mais praticidade no momento de contratar consórcio e escolher a melhor opção; mais praticidade nos leilões, na compra de studios etc. E qual a projeção de tempo e renda em cada mecanismo no caso concreto de cada cliente.', NULL, 'Ter mais explicações claras e que passem segurança na parte prática de operacionalizar os mecanismos com base no estudo da minha situação financeira atual.', 'Sinto falta de uma explicação mais clara e segura de uma projeção para cada mecanismo na minha situação financeira específica. Também acredito que o estrategista poderia levar em consideração alguns planos pessoais, por exemplo: se tenho um plano de comprar um carro novo (ou uma viagem, ou mudar de casa para uma melhor), como isso poderia se encaixar no planejamento e nos mecanismos de construção de ativos, de modo a ficar bem claro como se fosse para uma criança de 12 anos entender.', NULL, NULL, 'legado', 'NPS_Q1_2026_ENVIADO_MARCO.xlsx', 'pharus', NULL, 'aba PHARUS da planilha', 'MARÇO') ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente = EXCLUDED.cliente, id_cliente = EXCLUDED.id_cliente, programa = EXCLUDED.programa, ep = EXCLUDED.ep, nota_nps = EXCLUDED.nota_nps, categoria = EXCLUDED.categoria, nota_estrategista = EXCLUDED.nota_estrategista, nota_backoffice = EXCLUDED.nota_backoffice, nota_qv360 = EXCLUDED.nota_qv360, nota_arquitetura_patrimonial = EXCLUDED.nota_arquitetura_patrimonial, plano_patrimonial = EXCLUDED.plano_patrimonial, plano_apresentado = EXCLUDED.plano_apresentado, caminho = EXCLUDED.caminho, momento = EXCLUDED.momento, motivo_nota = EXCLUDED.motivo_nota, melhoria = EXCLUDED.melhoria, razao_positiva = EXCLUDED.razao_positiva, retencao_5_anos = EXCLUDED.retencao_5_anos, comentario_adicional = EXCLUDED.comentario_adicional, reunioes_realizadas = EXCLUDED.reunioes_realizadas, inicio_programa = EXCLUDED.inicio_programa, versao_formulario = EXCLUDED.versao_formulario, fonte_arquivo = EXCLUDED.fonte_arquivo, fonte_aba = EXCLUDED.fonte_aba, id_resposta = EXCLUDED.id_resposta, ref_programa = EXCLUDED.ref_programa, ref_ep = EXCLUDED.ref_ep, imported_at = now();
